list_currencies.code:
final response = await client.currencies
    .listCurrencies(queryParams: {'search': 'dollar', 'active': true});
final currencies = (response.map as Map)['currencies'] as List;
for (final currency in currencies) {
  print('${(currency as Map)['code']} ${currency['name']}');
}

count_currencies.code:
final response = await client.currencies
    .countCurrencies(queryParams: {'search': 'dollar', 'active': true});
print((response.map as Map)['total']);

create_currency.code:
final response = await client.currencies.createCurrency({
  'name': 'Example Dollar',
  'code': 'XEX',
  'symbol': '\$',
  'country': 'NZ',
  'conversion_rate': 1.2345,
  'precision': 2,
  'rounding': 'nearest',
  'active': true,
});
final currency = (response.map as Map)['currency'] as Map;
print('${currency['id']} ${currency['code']}');

get_currency.code:
final response = await client.currencies
    .getCurrency(1234, queryParams: {'field_metadata': true});
final body = response.map as Map;
final currency = body['currency'] as Map;
print('${currency['code']} ${currency['conversion_rate']}');
print((body['field_metadata'] as Map).keys);

head_currency.code:
final response = await client.currencies.headCurrency(1234);
print(response.statusCode);
print(response.headers['etag']);

update_currency.code:
final response = await client.currencies.updateCurrency(1234, {
  'name': 'Example Dollar',
  'code': 'XEX',
  'symbol': '\$',
  'country': {'code': 'US'},
  'conversion_rate': 1.5,
  'precision': 3,
  'rounding': 'up',
  'active': false,
});
final currency = (response.map as Map)['currency'] as Map;
print('${currency['conversion_rate']} ${currency['rounding']}');

patch_currency.code:
final response = await client.currencies
    .patchCurrency(1234, {'conversion_rate': 2.5});
final currency = (response.map as Map)['currency'] as Map;
print('${currency['code']} ${currency['conversion_rate']}');

set_base_currency.code:
final response = await client.currencies.setBaseCurrency(1234);
final body = response.map as Map;
print((body['currency'] as Map)['code']);
print(body['previous_base']);
